-- Phase 3a, migration race_results (E10s-1): the RaceResult table and the weekly prediction log.
--
-- Generated by `prisma migrate diff`, then edited by hand in the INSERT of the PredictionLog
-- redefine only:
--   * "loggedOn" (the runner's local day the prediction was made) is required with no database
--     default, so each existing row gets the day in its own "inputs": "$.today", written by every
--     earlier release. A row whose "inputs" are not JSON or carry no text date falls back to the
--     UTC day of "createdAt", which SQLite holds as text (the driver writes ISO 8601 with +00:00,
--     the column default writes 'YYYY-MM-DD HH:MM:SS') or as integer milliseconds since the epoch
--     (the form of Prisma's own query engine); all three are read. Nothing else decides, so the
--     migration cannot fail on an odd row.
--   * "weekStart" is the Monday of that day: strftime('%w') counts Sunday as 0, so the days back to
--     Monday are (weekday + 6) % 7.
-- Every other column is copied as it is and no row is deleted. Weeks that hold several rows stay as
-- they are; the API collapses them on read (design 11.3, question 14). Nothing references
-- PredictionLog, so no cascade fires while the table is dropped with the foreign keys off.

-- CreateTable
CREATE TABLE "RaceResult" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "goalId" TEXT NOT NULL,
    "activityId" TEXT,
    "date" TEXT NOT NULL,
    "distanceM" INTEGER NOT NULL,
    "gainM" INTEGER,
    "outcome" TEXT NOT NULL,
    "timeSec" INTEGER,
    "note" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "RaceResult_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "RaceResult_goalId_fkey" FOREIGN KEY ("goalId") REFERENCES "Goal" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "RaceResult_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "Activity" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);

-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_PredictionLog" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "goalId" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "method" TEXT NOT NULL,
    "predictedSec" INTEGER NOT NULL,
    "lowSec" INTEGER NOT NULL,
    "highSec" INTEGER NOT NULL,
    "inputs" TEXT NOT NULL DEFAULT '{}',
    "actualSec" INTEGER,
    "weekStart" TEXT NOT NULL,
    "loggedOn" TEXT NOT NULL,
    CONSTRAINT "PredictionLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "PredictionLog_goalId_fkey" FOREIGN KEY ("goalId") REFERENCES "Goal" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
INSERT INTO "new_PredictionLog" ("actualSec", "createdAt", "goalId", "highSec", "id", "inputs", "loggedOn", "lowSec", "method", "predictedSec", "userId", "weekStart")
SELECT
    "actualSec",
    "createdAt",
    "goalId",
    "highSec",
    "id",
    "inputs",
    "loggedOn",
    "lowSec",
    "method",
    "predictedSec",
    "userId",
    date("loggedOn", '-' || ((CAST(strftime('%w', "loggedOn") AS INTEGER) + 6) % 7) || ' days')
FROM (
    SELECT
        *,
        coalesce(
            CASE WHEN json_valid("inputs") AND json_type("inputs", '$.today') = 'text' THEN date(json_extract("inputs", '$.today')) END,
            CASE WHEN typeof("createdAt") IN ('integer', 'real') THEN date("createdAt" / 1000, 'unixepoch') ELSE date("createdAt") END,
            date('now')
        ) AS "loggedOn"
    FROM "PredictionLog"
);
DROP TABLE "PredictionLog";
ALTER TABLE "new_PredictionLog" RENAME TO "PredictionLog";
CREATE INDEX "PredictionLog_userId_goalId_createdAt_idx" ON "PredictionLog"("userId", "goalId", "createdAt");
CREATE INDEX "PredictionLog_userId_goalId_weekStart_idx" ON "PredictionLog"("userId", "goalId", "weekStart");
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;

-- CreateIndex
CREATE UNIQUE INDEX "RaceResult_goalId_key" ON "RaceResult"("goalId");

-- CreateIndex
CREATE UNIQUE INDEX "RaceResult_activityId_key" ON "RaceResult"("activityId");
